function renderModeratorFormat(){
 let panel=$('moderatorFormat');if(!panel){panel=document.createElement('div');panel.id='moderatorFormat';$('dialogMeta').after(panel);}
 panel.replaceChildren();panel.hidden=communityState?.moderator!==true||activeCommunityVideo?.archive===true;if(panel.hidden||!activeCommunityVideo)return;
 panel.innerHTML='<h3>Moderator: video format</h3><label>Format <select id="moderatorFormatChoice"><option value="SHORT">Short</option><option value="FULL_LENGTH">Full-length</option><option value="UNKNOWN">Unknown / needs review</option></select></label><button type="button" class="outline-button" id="saveModeratorFormat">Save format</button><button type="button" class="outline-button" id="excludeModeratorVideo">Exclude video</button><button type="button" class="outline-button" id="manageModeratorVideo">Unapprove / hide / delete</button><p role="status" id="moderatorFormatStatus"></p>';
 $('moderatorFormatChoice').value=['SHORT','FULL_LENGTH','UNKNOWN'].includes(activeCommunityVideo.format)?activeCommunityVideo.format:'UNKNOWN';
 const act=async(exclude)=>{const video=activeCommunityVideo;if(!video||communityState?.moderator!==true)return;const format=$('moderatorFormatChoice').value;const buttons=[...panel.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{if(exclude&&!confirm('Exclude this video from the Missioned Souls catalog?'))return;const result=await performerApi(exclude?'/review':'/format',exclude?{id:'missioned-souls',videos:[video.id],decision:'exclude'}:{videoId:video.id,format});if(activeCommunityVideo?.id===video.id)$('moderatorFormatStatus').textContent=result.message;await reloadMemberCatalog();if(exclude&&activeCommunityVideo?.id===video.id)$('videoDialog').close();else if(activeCommunityVideo?.id===video.id)activeCommunityVideo.format=format;}catch(e){if(activeCommunityVideo?.id===video.id)$('moderatorFormatStatus').textContent=e.message;}finally{buttons.forEach(b=>b.disabled=false);}};
 $('manageModeratorVideo').onclick=async()=>{const id=activeCommunityVideo.id;$('videoDialog').close();await navigate('classification-review');$('catalogManagementSearch').elements.q.value=id;catalogManagementOffset=0;await loadCatalogManagement();$('catalogManagementPanel').scrollIntoView({block:'start'});};
 $('saveModeratorFormat').onclick=()=>act(false);$('excludeModeratorVideo').onclick=()=>act(true);
}
