let followingGroupsOpen=false;
function followingGroupsMarkup(){
 const groups=sortFollowingGroups(dashboard.followingGroups||[],'name'),active=groups.find(g=>g.active);
 return `<details class="panel following-groups" id="followingGroups" ${followingGroupsOpen?'open':''}><summary><h2>Following groups</h2></summary><div class="following-groups-content"><p>Save combinations of reactors and songs. Switching groups automatically saves changes to your active manual group. YouTube imports is managed separately: imports add to that group without changing your other groups. Select it to use those reactors in Following. Removing a reactor there removes it from the import group; disconnecting YouTube clears tracked imports only. Your groups are private to your account.</p><details class="youtube-imports-group-help"><summary>YouTube imports group</summary><p>The YouTube imports group is managed by importing and removing reactors, so it cannot be renamed, deleted, cloned, or overwritten with current follows. To remove an individual reactor, select that group in Following and choose Unfollow. Independently saved memberships in manual groups remain unchanged.</p></details><p role="status">${active?'Active group: '+escapeHtml(active.name):'Using current follows. Save them before switching to a group.'}</p><form id="createFollowingGroup"><label>New group name<input name="name" required maxlength="60" placeholder="For example: Rock favorites"></label><button class="primary-button" ${active?.kind==='youtube'?'disabled title="Switch to a manual group before creating a new group"':''}>Save current follows as new group</button></form><label>Saved group<select id="followingGroupChoice"><option value="">Choose a group</option>${groups.map(g=>`<option value="${g.id}" ${g.active?'selected':''}>${escapeHtml(g.name)} (${g.active&&g.kind!=='youtube'?dashboard.follows.filter(f=>f.kind==='reactor'||f.kind==='song').length:g.follows.length} follows)</option>`).join('')}</select></label><div class="follow-row"><button class="outline-button" data-group-action="rename">Rename</button><button class="text-button" data-group-action="delete">Delete group</button></div><p class="subtle">An empty active group shows no followed reactions. Hidden reactors remain hidden. Reset buttons clear current follows and leave saved groups available.</p></div></details>`;
}
function bindFollowingGroups(){
 $('followingGroups').ontoggle=e=>{followingGroupsOpen=e.currentTarget.open;};
 const choice=$('followingGroupChoice'),buttons=[...document.querySelectorAll('[data-group-action]')];
 buttons.forEach(button=>{button.disabled=dashboard.followingGroups.find(g=>g.id===choice.value)?.kind==='youtube'&&button.dataset.groupAction!=='activate';});
 const restoreChoice=()=>{choice.value=dashboard.followingGroups.find(g=>g.active)?.id||'';};
 choice.onchange=()=>{if(!choice.value){restoreChoice();return;}return changeGroup('activate');};
 $('createFollowingGroup').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;await action(()=>socialApi('/following-group',{action:'create',name:e.currentTarget.elements.name.value}),'Following group saved.');if(button.isConnected)button.disabled=false;};
 async function changeGroup(operation){
  if(choice.disabled)return;
  const id=$('followingGroupChoice').value;if(!id){notice('Choose a saved group first.');return;}
  const group=dashboard.followingGroups.find(g=>g.id===id);let name;
  if(group.kind==='youtube'&&operation!=='activate'){notice('YouTube imports is managed through importing, individual removal, or disconnecting YouTube.');return;}
  if(operation==='rename'){name=prompt('Group name',group.name);if(!name)return;}
  if(operation==='delete'&&!confirm('Delete this saved group? Current follows will remain.'))return;
  if(operation==='activate'&&!dashboard.followingGroups.some(g=>g.active)&&dashboard.follows.some(f=>f.kind==='reactor'||f.kind==='song')&&!confirm('Switch to this group and replace current follows? Save current follows as a new group first if you want to keep them.')){restoreChoice();return;}
  choice.disabled=true;buttons.forEach(b=>b.disabled=true);
  try{const saved=await action(()=>socialApi('/following-group',{id,action:operation,...(name?{name}:{})}),'Following group '+(operation==='activate'?'activated.':'saved.'));if(!saved&&operation==='activate')restoreChoice();}
  finally{if(choice.isConnected)choice.disabled=false;buttons.forEach(b=>{if(b.isConnected)b.disabled=false;});}
 }
 buttons.forEach(button=>button.onclick=()=>changeGroup(button.dataset.groupAction));
}

function followingName(f){return f.kind==='reactor'?(catalog.channels.find(c=>c.id===f.target)?.name||f.target):f.target;}
function followingRank(f,personal=false){
 if(f.kind==='reactor')return personal?myReactorRating(f.target)??null:reactorScore(f.target)?.average??null;
 const ratings=catalog.videos.filter(v=>!(dashboard.hiddenReactors||[]).some(h=>h.channel_id===v.channelId)&&`${v.song||''} ${v.title||''}`.toLowerCase().includes(f.target.toLowerCase())).map(v=>scoreMap.get(v.id)?.average).filter(x=>x!=null);
 return ratings.length?ratings.reduce((sum,x)=>sum+Number(x),0)/ratings.length*20:null;
}
function sortFollowingRows(rows,sort){
 if(rows.length&&rows.every(row=>row.kind==='reactor')){
  const channels=new Map(catalog.channels.map(c=>[c.id,c])),discovery=new Map();
  for(const video of catalog.videos||[]){if(video.performerId!=='missioned-souls'||video.isOfficial)continue;const date=Date.parse(video.publishedAt);if(Number.isFinite(date))discovery.set(video.channelId,Math.min(discovery.get(video.channelId)??Infinity,date));}
  return [...rows].sort((a,b)=>{const first=channels.get(a.target)||{id:a.target,name:a.target},second=channels.get(b.target)||{id:b.target,name:b.target},names=first.name.localeCompare(second.name);
   return sort==='newest'?(discovery.get(second.id)??0)-(discovery.get(first.id)??0)||names:sort==='ranked'?reactorRankValue(second.id)-reactorRankValue(first.id)||(reactorScore(second.id)?.count||0)-(reactorScore(first.id)?.count||0)||names:sort==='personal'?Number(myReactorRating(second.id)??-1)-Number(myReactorRating(first.id)??-1)||names:sort==='subscribers'?(second.subscribers??-1)-(first.subscribers??-1):names;
  });
 }
 return [...rows].sort((a,b)=>{
 const names=followingName(a).localeCompare(followingName(b),undefined,{sensitivity:'base',numeric:true});
 return sort==='name'?names:Number(followingRank(b,sort==='personal')??-1)-Number(followingRank(a,sort==='personal')??-1)||names;
});}
function followingGroupRank(group){const rows=group.active?dashboard.follows:group.follows;const ranks=rows.filter(f=>f.kind==='reactor'||f.kind==='song').map(f=>followingRank(f)).filter(x=>x!=null);return ranks.length?ranks.reduce((sum,x)=>sum+Number(x),0)/ranks.length:null;}
function sortFollowingGroups(groups,sort){return [...groups].sort((a,b)=>(sort==='ranked'?Number(followingGroupRank(b)??-1)-Number(followingGroupRank(a)??-1):0)||a.name.localeCompare(b.name,undefined,{sensitivity:'base',numeric:true})||a.id.localeCompare(b.id));}
function followingRankLabel(f){const rank=followingRank(f);return f.kind==='reactor'?`Community: ${rank==null?'Unrated':Number(rank).toFixed(1)+'/100'} · Yours: ${myReactorRating(f.target)??'Unrated'}`:`Matching videos: ${rank==null?'Unrated':(rank/20).toFixed(1)+'/5'}`;}
function followingSortControl(key,personal){return `<label>Sort ${key==='followingGroupSort'?'groups':key==='followingReactorSort'?'reactors':'songs'}<select data-following-sort="${key}">${(key==='followingReactorSort'?[...$('reactorSort').options].map(option=>[option.value,option.textContent]):[['name','Alphabetical (A–Z)'],['ranked',key==='followingSongSort'?'Matching video rating (highest first)':'Community ranking (highest first)'],...(personal?[['personal','Your ranking (highest first)']]:[])]).map(([value,label])=>`<option value="${value}" ${(prefs[key]||'name')===value?'selected':''}>${label}</option>`).join('')}</select></label>`;}
function bindFollowingSorts(){document.querySelectorAll('[data-following-sort]').forEach(select=>select.onchange=async()=>{const key=select.dataset.followingSort,old=prefs[key];prefs[key]=select.value;select.disabled=true;try{await socialApi('/preferences',currentSettings());renderFollowing();}catch(e){prefs[key]=old;select.disabled=false;select.value=old||'name';notice(e.message);}});}

;(()=>{const toolbar=document.querySelector('#feed .toolbar');const filters=document.createElement('div');filters.id='feed-search-filters';filters.hidden=true;toolbar.before(filters);const actions=document.createElement('div');actions.className='feed-search-actions';actions.innerHTML='<label class="include-shorts"><input id="includeShorts" type="checkbox">Include Shorts</label><button type="button" id="clearFeedFilters" class="outline-button">Clear filters</button><button type="button" class="feed-search-toggle" aria-label="Show search and filters" title="Show search and filters" aria-controls="feed-search-filters" aria-expanded="false"><svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/></svg></button>';filters.before(actions);const following=document.getElementById('followingScope')?.closest('.panel');if(following)filters.append(following);filters.append(document.querySelector('#feed .performer-strip'),toolbar);actions.querySelector('#clearFeedFilters').onclick=clearFeedFilters;const toggle=actions.querySelector('.feed-search-toggle');toggle.onclick=()=>{const open=filters.hidden;filters.hidden=!open;toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Hide search and filters':'Show search and filters');toggle.title=toggle.getAttribute('aria-label');if(open)document.getElementById('searchInput').focus();};filters.addEventListener('keydown',e=>{if(e.key==='Escape'){filters.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Show search and filters');toggle.title='Show search and filters';toggle.focus();}});const shorts=document.getElementById('includeShorts');shorts.checked=!prefs.hideShorts;shorts.onchange=()=>{prefs.hideShorts=!shorts.checked;state.format='all';state.visible=24;renderVideos();};})();

function videoDiscussionActionsMarkup(v){return '<label>Watch status'+watchSelect(v)+'</label><button type="button" class="outline-button" data-hide-reactor="'+escapeHtml(v.channelId)+'">Hide reactor</button><button type="button" class="outline-button" data-follow-reactor="'+escapeHtml(v.channelId)+'">'+(follows('reactor',v.channelId)?'✓ Following · Unfollow':'+ Follow reactor')+'</button>';}
function renderVideoActions(){
 const v=activeCommunityVideo;if(!v)return;
 let mount=$('videoDiscussionActions');if(!mount){mount=document.createElement('div');mount.id='videoDiscussionActions';mount.className='video-discussion-actions';$('videoDialogBody').prepend(mount);}
 mount.hidden=!!v.archive;if(v.archive){mount.replaceChildren();return;}mount.innerHTML=videoDiscussionActionsMarkup(v);bindHiddenReactors(mount);
 mount.querySelector('[data-watch]').onchange=async e=>{e.target.disabled=true;try{await saveWatch(v.id,{status:e.target.value});}finally{if(e.target.isConnected)e.target.disabled=false;}};
 mount.querySelector('[data-follow-reactor]').onclick=async e=>{e.target.disabled=true;try{await toggleFollow('reactor',v.channelId);}finally{if(e.target.isConnected)e.target.disabled=false;}};
}

